-    return await this.constructionService.getOrCreateProject(propertyId, orgId);
&lt;/span&gt;&lt;span class="gi"&gt;+  async getProject(@Query('propertyId') propertyId: string, @Req() req: Request, @Context() ctx: ExecutionContext) {
+    const orgId = TenantContext.getOrganizationId(ctx);
+    return await this.constructionService.getOrCreateProject(propertyId, orgId);
&lt;/span&gt;   }
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;Key points:&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;The controller now receives &lt;code&gt;@Context() ctx: ExecutionContext&lt;/code&gt; (Nest’s built‑in injection) to keep the method signature identical for testing.&lt;/li&gt;
&lt;li&gt;All downstream calls receive &lt;code&gt;orgId&lt;/code&gt; explicitly.&lt;/li&gt;
&lt;/ul&gt;

&lt;h3&gt;


